import React from 'react';
import classNames from 'classnames';
import { useTranslation } from '@getvim/translate';
import RoundedImage from '../roundedImage';

import es from './translations/es.json';
import './index.less';
import { DoctorPlaceholder, SvgCareTeam } from '../svgs';
import messages from './translations/messages';

export type ProviderProps = {
  profilePicture?: string;
  careTeam?: boolean;
};

export type ProviderLogoProps = {
  provider: ProviderProps;
  /**
   * The css class name based on doctor img css class.
   */
  containerClass: string;
  /**
   * An alternative custom css class instead of @containerClass.
   */
  className: string;
  hidePicture: boolean;
};

function ProviderLogo({
  provider: { profilePicture, careTeam },
  containerClass,
  className,
  hidePicture,
}: ProviderLogoProps) {
  const intl = useTranslation({ es });
  let providerImage = (
    <div className={classNames('doctor-img ', containerClass)}>
      <DoctorPlaceholder className={classNames('doctor-img ', containerClass)} />
    </div>
  );
  if (profilePicture && !hidePicture) {
    providerImage = (
      <RoundedImage
        className={classNames(className || 'doctor-img', containerClass)}
        src={profilePicture}
      />
    );
  }

  return (
    <span className="pic-wrap">
      {providerImage}
      {careTeam && (
        <div className="care-team">
          <SvgCareTeam />
          <span className="text-11 text-semibold text-dark">
            {intl.formatMessage(messages.careTeamMessage)}
          </span>
        </div>
      )}
    </span>
  );
}

ProviderLogo.defaultProps = {
  className: undefined,
  containerClass: 'big',
  hidePicture: false,
};

export default ProviderLogo;
